struct link { char *href; char *rel; };                 /* copied from header data */
struct link links[16]; struct curl_header *h;
curl_easy_header(easy, "Link", 0, CURLH_HEADER, -1, &h);/* carrier: response header */
size_t n = parse_link_header(h->value, links, 16);      /* RFC 8288 B.2 parse+copy */
for (struct link *l = links; l < links + n; l++) {
    if (strcmp(l->rel, "payment")) continue;            /* consumer: rel dispatch */
    CURLU *u = curl_url();                              /* resolver */
    curl_url_set(u, CURLUPART_URL, base, 0);            /* base = request URL */
    curl_url_set(u, CURLUPART_URL, l->href, 0);         /* RFC 3986 relative resolve */
    char *abs; curl_url_get(u, CURLUPART_URL, &abs, 0);
    curl_easy_setopt(follow, CURLOPT_URL, abs);         /* dereference the link */
    curl_easy_perform(follow);
    curl_free(abs); curl_url_cleanup(u);                /* curl_free, never free() */
}
